import re
import six
from abc import abstractproperty, ABCMeta
from .exception import ErrorFoundInCommandLineOutput


@six.add_metaclass(ABCMeta)
class BaseErrorChecker(object):

    def __init__(self):
        self.regexp_generic_errors = [
            re.compile("(\[ERROR\]\s*Cannot connect to.*\n[^\n]*Operations finished)")
        ]

    @abstractproperty
    def regexp_error(self):
        """Returns regexp required to find error."""

    def check(self, output):
        """Raises error if error string is available in provided output."""
        self._check_if_output_contains_generic_errors(output)
        regexp_error = self._compile_regexp_if_needed()
        if regexp_error is not None:
            self._check_if_output_contains_error(output, regexp_error)

    def _check_if_output_contains_error(self, output, regexp_error):
        result = regexp_error.search(output)
        if result:
            raise ErrorFoundInCommandLineOutput(result, output)

    def _compile_regexp_if_needed(self):
        if isinstance(self.regexp_error, six.string_types):
            return re.compile(self.regexp_error)
        return self.regexp_error

    def _check_if_output_contains_generic_errors(self, output):
        for regexp_error in self.regexp_generic_errors:
            result = regexp_error.search(output)
            if result:
                raise ErrorFoundInCommandLineOutput(result, output)


class SwUpdateErrorChecker(BaseErrorChecker):
    def __init__(self):
        super(SwUpdateErrorChecker, self).__init__()

    @property
    def regexp_error(self):
        """Returns regexp required to find error."""
        return re.compile("(\[ERROR\]\s*SW update failed)")


class CollectFilesErrorChecker(BaseErrorChecker):
    def __init__(self):
        super(CollectFilesErrorChecker, self).__init__()

    @property
    def regexp_error(self):
        """Returns regexp required to find error."""
        return re.compile("(\[ERROR\]\s*Failed to get siteconf from)")


class CommissioningErrorChecker(BaseErrorChecker):
    def __init__(self):
        super(CommissioningErrorChecker, self).__init__()

    @property
    def regexp_error(self):
        """Returns regexp required to find error."""
        return re.compile("(\[ERROR\] Activation timeout with)")


class NoErrorChecker(BaseErrorChecker):
    """Checker which is not checking output."""

    @property
    def regexp_error(self):
        """Returns regexp required to find error."""
        return None


class ErrorChecker(object):

    SUPPORTED_TOOL_OPERATIONS = {
        'swupdate': SwUpdateErrorChecker,
        'collectfiles': CollectFilesErrorChecker,
        'commissioning': CommissioningErrorChecker,
    }

    def __new__(cls, op, *args, **kwargs):
        if op in cls.SUPPORTED_TOOL_OPERATIONS:
            return cls.SUPPORTED_TOOL_OPERATIONS[op]()
        else:
            return NoErrorChecker()
